10|export const setNestedPayloadValue = (
11|  target: Record<string, unknown>,
12|  path: string,
13|  value: unknown,
14|): void => {
15|  const segments = path.split('.').map((segment) => segment.trim()).filter(Boolean);
16|  if (segments.length === 0) {
17|    return;
18|  }
19|
20|  let cursor: Record<string, unknown> = target;
21|  for (let index = 0; index < segments.length - 1; index += 1) {
22|    const segment = segments[index];
23|    const next = cursor[segment];
24|    if (!next || typeof next !== 'object' || Array.isArray(next)) {
25|      cursor[segment] = {};
26|    }
27|    cursor = cursor[segment] as Record<string, unknown>;
28|  }
29|
30|  cursor[segments[segments.length - 1]] = value;
31|};
