76|export const applyPayloadFieldTransform = (
77|  value: FormDataEntryValue | null,
78|  transform?: PayloadFieldTransform,
79|): unknown => {
80|  const raw = value === null ? '' : String(value);
81|
82|  switch (transform) {
83|    case 'number': {
84|      const parsed = Number(raw);
85|      return Number.isFinite(parsed) ? parsed : raw;
86|    }
87|    case 'boolean':
88|      return raw === 'true' || raw === '1' || raw === 'on';
89|    case 'commaSeparatedArray':
90|      return raw.split(',').map((entry) => entry.trim()).filter(Boolean);
91|    default:
92|      return raw;
93|  }
94|};
