96|export const buildPayloadFromFormData = (
97|  formData: FormData,
98|  payloadMapping?: Record<string, string>,
99|  fieldTransforms?: Record<string, PayloadFieldTransform>,
100|): Record<string, unknown> => {
101|  if (!payloadMapping || Object.keys(payloadMapping).length === 0) {
102|    const payload: Record<string, unknown> = {};
103|    formData.forEach((value, key) => {
104|      payload[key] = applyPayloadFieldTransform(value, fieldTransforms?.[key]);
105|    });
106|    return payload;
107|  }
108|
109|  const payload: Record<string, unknown> = {};
110|  for (const [apiPath, formField] of Object.entries(payloadMapping)) {
111|    const transformed = applyPayloadFieldTransform(formData.get(formField), fieldTransforms?.[apiPath]);
112|    if (isNestedPayloadPath(apiPath)) {
113|      setNestedPayloadValue(payload, apiPath, transformed);
114|    } else {
115|      payload[apiPath] = transformed;
116|    }
117|  }
118|
119|  return payload;
